using HRM.Application.Contracts.Recruitment;using HRM.Components.Shared;using HRM.DTOs;using HRM.Models;using HRM.Models.Recruitment;using HRM.Services.Interfaces;using Microsoft.EntityFrameworkCore;namespace HRM.Services;
public sealed class RecruitmentAssessmentService(IDbContextFactory<HrmTeContext> factory,IUserAccessService access,IOperationLogService logs):IRecruitmentAssessmentService{async Task<(int Org,int User)>Auth(){var o=await access.GetCurrentOrganisationIdAsync();var a=await access.RequireContextAsync();if(o<=0||!await access.HasOrganisationAccessAsync(o)||!await access.HasPermissionAsync("Recruitment.Manage"))throw new UnauthorizedAccessException("Recruitment management permission is required.");return(o,a.UserId);}public async Task<ServiceResult>CreateAsync(CreateRecruitmentAssessmentInput i,CancellationToken ct=default){if(i.VacancyId<=0||string.IsNullOrWhiteSpace(i.Type)||string.IsNullOrWhiteSpace(i.TemplateCode)||i.ScheduledAtUtc<=DateTime.UtcNow)return ServiceResult.Fail("Provide an assessment type, official template and future schedule.");var(o,_)=await Auth();await using var d=await factory.CreateDbContextAsync(ct);if(!await d.RecruitmentVacancies.AnyAsync(x=>x.Id==i.VacancyId&&x.OrganisationId==o&&x.Status=="Published",ct))return ServiceResult.Fail("Select a published vacancy.");if(await d.RecruitmentResultPublications.AnyAsync(x=>x.RecruitmentVacancyId==i.VacancyId,ct))return ServiceResult.Fail("Merit results are published and frozen; assessments cannot be added.");var l=await logs.CreateAsync(d,SharedConfig.OperationLogActionTypes.REQUESTS_CREATE,$"Recruitment {i.Type} assessment created for vacancy {i.VacancyId}.");d.RecruitmentAssessments.Add(new RecruitmentAssessment{RecruitmentVacancyId=i.VacancyId,OrganisationId=o,Type=i.Type.Trim(),TemplateCode=i.TemplateCode.Trim(),ScheduledAtUtc=i.ScheduledAtUtc,OperationLogId=l.OperationLogId});await d.SaveChangesAsync(ct);return ServiceResult.Ok("Assessment created.");}public async Task<ServiceResult>SubmitScorecardAsync(SubmitPanelScorecardInput i,CancellationToken ct=default){if(i.AssessmentId<=0||i.ApplicationId<=0||i.TotalScore<0||i.TotalScore>100||string.IsNullOrWhiteSpace(i.CriterionScoresJson)||i.CriterionScoresJson.Length>16000)return ServiceResult.Fail("Provide a valid scorecard.");var(o,u)=await Auth();await using var d=await factory.CreateDbContextAsync(ct);var a=await d.RecruitmentAssessments.SingleOrDefaultAsync(x=>x.Id==i.AssessmentId&&x.OrganisationId==o,ct)??throw new UnauthorizedAccessException();if(await d.RecruitmentResultPublications.AnyAsync(x=>x.RecruitmentVacancyId==a.RecruitmentVacancyId,ct))return ServiceResult.Fail("Merit results are published and frozen; scores can no longer be modified.");var declaration=await d.RecruitmentPanelConflictDeclarations.SingleOrDefaultAsync(x=>x.RecruitmentVacancyId==a.RecruitmentVacancyId&&x.DeclaredByUserId==u,ct);if(declaration is null)return ServiceResult.Fail("Record a conflict declaration before submitting scores.");var policyId=await d.RecruitmentVacancies.Where(x=>x.Id==a.RecruitmentVacancyId).Select(x=>x.RecruitmentPolicyVersionId).SingleAsync(ct);var template=await d.RecruitmentOfficialTemplates.SingleOrDefaultAsync(x=>x.RecruitmentPolicyVersionId==policyId&&x.TemplateCode==a.TemplateCode&&x.IsActive&&x.VerificationStatus=="Verified",ct);if(template is null)return ServiceResult.Fail("A verified official scoring template is required.");if(!RecruitmentScoreValidation.TryCalculate(template.TemplateDefinitionJson,i.CriterionScoresJson,out var computed)||computed!=i.TotalScore)return ServiceResult.Fail("Criterion scores must match the verified template and calculated total.");if(await d.RecruitmentPanelConflictDeclarations.AnyAsync(x=>x.RecruitmentVacancyId==a.RecruitmentVacancyId&&x.DeclaredByUserId==u&&x.HasConflict,ct))return ServiceResult.Fail("A declared conflict blocks score submission.");if(!await d.RecruitmentApplications.AnyAsync(x=>x.Id==i.ApplicationId&&x.RecruitmentVacancyId==a.RecruitmentVacancyId&&x.Status=="Shortlisted",ct))return ServiceResult.Fail("Only shortlisted applicants may be assessed.");if(await d.RecruitmentPanelScorecards.AnyAsync(x=>x.RecruitmentAssessmentId==a.Id&&x.RecruitmentApplicationId==i.ApplicationId&&x.ScorerUserId==u,ct))return ServiceResult.Fail("Your scorecard is already locked.");var l=await logs.CreateAsync(d,SharedConfig.OperationLogActionTypes.REQUESTS_UPDATE,$"Locked scorecard submitted for assessment {a.Id}.");d.RecruitmentPanelScorecards.Add(new RecruitmentPanelScorecard{RecruitmentAssessmentId=a.Id,RecruitmentApplicationId=i.ApplicationId,ScorerUserId=u,TotalScore=i.TotalScore,CriterionScoresJson=i.CriterionScoresJson,SubmittedAtUtc=DateTime.UtcNow,IsLocked=true,OperationLogId=l.OperationLogId});await d.SaveChangesAsync(ct);return ServiceResult.Ok("Scorecard submitted and locked.");}}
